/usr/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const findings = JSON.parse(fs.readFileSync('.exp_agent/findings_round_01.json', 'utf8'));
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_plan_01.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_completion_01.json', 'utf8'));
const seen = new Set();
for (const repair of report.entity_repairs) {
  if (repair.status "'!== '"'repaired') throw new Error("'`bad status: ${repair.rule} ${repair.relative_path}`);
  for (const location of repair.locations) seen.add(`${repair.rule}|${repair.relative_path}|${location.line}|${location.column}`);
  for (const key of ['"'entities', 'invariants', 'evidence', 'transformation']) if ("'!repair[key]?.length) throw new Error(`empty ${key}`);
}
for (const finding of findings) {
  const key = `${finding.rule}|${finding.relative_path}|${finding.line}|${finding.column}`;
  if (!seen.has(key)) throw new Error(`missing frozen location ${key}`);
}
const plannedRules = new Set(plan.rules.map(x => x.rule));
for (const rule of plannedRules) if (!report.selected_rules.includes(rule)) throw new Error(`missing selected rule ${rule}`);
console.log(JSON.stringify({findings: findings.length, reportLocations: seen.size, plannedRules: plannedRules.size, reportRepairs: report.entity_repairs.length, unresolvedExternal: report.unresolved_external.length}));
NODE'
